import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import { FaBook, FaChartLine, FaTasks } from "react-icons/fa";
import AlertBox from "./AlertBox";
import ProgressChart from "./ProgressChart";

function StudentDashboard() {
  const userId = localStorage.getItem("user_id");
  const userName = localStorage.getItem("user_name");

  const [courses, setCourses] = useState([]);
  const [progress, setProgress] = useState({});
  const [alert, setAlert] = useState(null);

  // fetch data
  const fetchCourses = useCallback(async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = res.data.courses || [];

      const enrollRes = await axios.get(
        `http://127.0.0.1:8000/enrollments/${userId}`
      );

      const enrolledIds = enrollRes.data.map((e) => e.course_id);

      const myCourses = allCourses.filter((c) =>
        enrolledIds.includes(c.id)
      );

      setCourses(myCourses);

      // fetch progress
      const progressRes = await axios.get(
        `http://127.0.0.1:8000/progress/${userId}`
      );

      const progressMap = {};
      progressRes.data.forEach((item) => {
        progressMap[item.course_id] = {
          completed_topics: item.completed_topics,
          total_topics: item.total_topics,
          status: item.status
        };
      });

      setProgress(progressMap);
    } catch (err) {
      console.error(err);
    }
  }, [userId]);

  useEffect(() => {
    fetchCourses();
  }, [fetchCourses]);

  // update progress
  const handleProgress = async (courseId, value) => {
    try {
      const response = await axios.post(
        "http://127.0.0.1:8000/update-progress",
        {
          user_id: parseInt(userId),
          course_id: courseId,
          completed_topics: parseInt(value)
        }
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      fetchCourses();
    } catch (err) {
      setAlert({
        message: "Failed to update progress",
        type: "error"
      });
    }
  };

  // summary
  const completedCount = Object.values(progress).filter(
    (p) => p.status === "Completed"
  ).length;

  // chart data
  const chartData = courses.map((course) => {
    const courseProgress = progress[course.id] || {
      completed_topics: 0,
      total_topics: 10
    };

    const percentage = Math.round(
      (courseProgress.completed_topics /
        courseProgress.total_topics) *
        100
    );

    return {
      course: course.title,
      progress: percentage
    };
  });

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      {/* welcome */}
      <h2 style={{ marginBottom: "10px" }}>
        Welcome, {userName}
      </h2>

      {/* cards */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3,1fr)",
          gap: "20px",
          marginBottom: "25px"
        }}
      >
        <div style={card("#ede7f6")}>
          <h3>Enrolled</h3>
          <p style={num}>{courses.length}</p>
        </div>

        <div style={card("#e3f2fd")}>
          <h3>Completed</h3>
          <p style={num}>{completedCount}</p>
        </div>

        <div style={card("#f3e5f5")}>
          <h3>Learning</h3>
          <p style={num}><FaTasks /></p>
        </div>
      </div>

      {/* courses */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(260px,1fr))",
          gap: "20px"
        }}
      >
        {courses.map((course) => {
          const courseProgress = progress[course.id] || {
            completed_topics: 0,
            total_topics: 10,
            status: "In Progress"
          };

          const percentage = Math.round(
            (courseProgress.completed_topics /
              courseProgress.total_topics) *
              100
          );

          return (
            <div key={course.id} style={box}>
              <FaBook size={25} color="#7b1fa2" />

              <h3>{course.title}</h3>
              <p>{course.description}</p>

              <p>
                <strong>Code:</strong> {course.subject_code}
              </p>

              {/* progress bar */}
              <div style={outer}>
                <div
                  style={{
                    ...inner,
                    width: `${percentage}%`
                  }}
                ></div>
              </div>

              <p>Progress: {percentage}%</p>
              <p>Status: {courseProgress.status}</p>

              <input
                type="number"
                id={`progress-${course.id}`}
                placeholder="Enter topics"
                style={input}
              />

              <button
                onClick={() => {
                  const value = document.getElementById(
                    `progress-${course.id}`
                  ).value;
                  handleProgress(course.id, value || 0);
                }}
                style={btn}
              >
                <FaChartLine /> Update
              </button>
            </div>
          );
        })}
      </div>

      {/* chart */}
      <ProgressChart data={chartData} />
    </div>
  );
}

/* styles */
const card = (bg) => ({
  background: bg,
  padding: "20px",
  borderRadius: "16px"
});

const num = {
  fontSize: "26px",
  fontWeight: "bold"
};

const box = {
  background: "#fff",
  padding: "20px",
  borderRadius: "16px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
};

const outer = {
  height: "10px",
  background: "#eee",
  borderRadius: "10px",
  margin: "10px 0"
};

const inner = {
  height: "100%",
  background: "#7b1fa2",
  borderRadius: "10px"
};

const input = {
  width: "100%",
  padding: "8px",
  marginTop: "8px"
};

const btn = {
  marginTop: "10px",
  width: "100%",
  padding: "10px",
  background: "#7b1fa2",
  color: "#fff",
  border: "none",
  borderRadius: "8px"
};

export default StudentDashboard;
